do $release$
declare payload jsonb:=$payload${"units":[{"id":"flow-purchase","before_en":"4d400efe427eb81a02ebc519bb4881d8","before_mk":"6530caaf6b6a7dcf90bc48c95cdce6aa","after_en":"ea81a9a8af3e87cd5dd01555f0ede25d","after_mk":"a0c8802835d68ab729b3f27702940b78","revision":2},{"id":"flow-no-unlock","before_en":"cd120c37fbf504ad2313c8883a5a7b4e","before_mk":"1cfc562b8cb8b6c1d135d4f16509b00e","after_en":"54db9cff2e5db676467a95cba029678c","after_mk":"66ad889088ba0dd512e80a31c9ca4406","revision":2},{"id":"flow-no-pitch","before_en":"939ed108a5833c2565747bf74665ea19","before_mk":"495fbe0f844e9b9388f0a2c0940abbab","after_en":"bd82b29caefc916e271cf3b6baa3862e","after_mk":"873c88b333c7020ec4798f4a1e6955aa","revision":2},{"id":"flow-reference","before_en":"1a8c67e473ac54b8b23cc5d6b41c876f","before_mk":"6e1fb3aad890a833c6ee9499d3ee597a","after_en":"a201fb728672c90ea7ae38926372990b","after_mk":"5ff027fd4cd8f7a71d345ce669c19db8","revision":3},{"id":"rapport-practice","before_en":"30b201eba4505e9dc6e721694842e6cb","before_mk":"6961e606d105c29a5fcda16ea9480fb4","after_en":"6bf5213fd2c02a773ae3ece728f9ae0d","after_mk":"a5d0fe8e67b178fc4465d4343db62ceb","revision":2},{"id":"pitch-examples","before_en":"498c3d9ac5f3a8f304e62e890df11e50","before_mk":"bd8968fe49f2ce40830c8c2e3f132f60","after_en":"f01f2e40026899c8dbf9d4d4bc692df2","after_mk":"7c4ea1634f49c80f3697dd39c0bdff8d","revision":2},{"id":"ppv-momentum","before_en":"124adca2b3955ba953f57f80594573bb","before_mk":"a608e98a7d5cb615fb711ede36645e03","after_en":"3858837902f5280c97c95600c8dd054c","after_mk":"002c47348d53342b25f33c4376ab4437","revision":1},{"id":"aftercare","before_en":"fb4f754dea1c83809296677a831547ef","before_mk":"a0146f3c2bd5bbcbbfaf8e68d427e560","after_en":"54729608f532ff0041a0c55d4cd9f34e","after_mk":"ad138b8a8838f2bf8d14520b2fabd26c","revision":2},{"id":"daily-offers","before_en":"f8491cce96cd135ec6ccfd22a7e8255b","before_mk":"e2f42011936feaf776f34fd18ad1ef6d","after_en":"ea8c12d23fd1cb6e0a6686b3e357408b","after_mk":"608df514e62bf03e3b47f88f14c11d26","revision":2}],"edits":[{"unit_id":"rapport-practice","field":"body","before":"The video specifically emphasizes remembering details and bringing them back up.","after":"Remember details and bring them back up.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"rapport-practice","field":"body_mk","before":"Видеото посебно нагласува паметење детали и нивно повторно споменување.","after":"Памети детали и повторно споменувај ги.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"rapport-practice","field":"body","before":"The video’s guidance is to keep showing up. There is no deadline on this path.","after":"Keep showing up. There is no deadline on this path.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"rapport-practice","field":"body_mk","before":"Насоката од видеото е да продолжиш да бидеш присутен. На оваа патека нема рок.","after":"Продолжи да бидеш присутен. На оваа патека нема рок.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"pitch-examples","field":"body","before":"The video provides these price levels:","after":"Example price levels:","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"pitch-examples","field":"body_mk","before":"Видеото ги дава овие ценовни нивоа:","after":"Примерни ценовни нивоа:","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"aftercare","field":"body","before":"The video uses an affectionate follow-up message that communicates enjoyment and asks the customer whether they enjoyed the interaction too.","after":"An affectionate follow-up message communicates enjoyment and asks the customer whether they enjoyed the interaction too.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"aftercare","field":"body_mk","before":"Видеото користи нежна дополнителна порака што пренесува уживање и го прашува клиентот дали и тој уживал во интеракцијата.","after":"Нежната дополнителна порака пренесува уживање и го прашува клиентот дали и тој уживал во интеракцијата.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"daily-offers","field":"body","before":"The video also introduces a Notion price-listing page.\n\nExample prices entered in the lesson include:","after":"Example prices:","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"daily-offers","field":"body_mk","before":"Видеото воведува и страница со ценовник во Notion.\n\nПримерните цени внесени во лекцијата вклучуваат:","after":"Примерни цени:","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"ppv-momentum","field":"body","before":"either send a timed follow-up like in the clip above OR","after":"either send a timed follow-up OR","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"ppv-momentum","field":"body_mk","before":"испрати темпирана дополнителна порака како во клипот погоре ИЛИ","after":"испрати темпирана дополнителна порака ИЛИ","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-purchase","field":"body","before":"*The node's detailed explanatory text is not fully displayed in the recording, so additional rules beyond its label and pacing cannot be confirmed.*","after":"*Additional rules beyond this node’s label and pacing are not specified.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-purchase","field":"body_mk","before":"*Деталниот објаснувачки текст на јазолот не е целосно прикажан во снимката, па не може да се потврдат дополнителни правила освен неговата ознака и темпо.*","after":"*Не се наведени дополнителни правила освен ознаката и темпото на овој јазол.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-unlock","field":"body","before":"*The Stage 2 heading and its transition to the persuasion step are visible in the recording. The detailed instructions are provided in Step 11.*","after":"*The detailed instructions are provided in Step 11.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-unlock","field":"body_mk","before":"*Насловот на Фаза 2 и преминот кон чекорот на убедување се видливи во снимката. Деталните упатства се дадени во Чекор 11.*","after":"*Деталните упатства се дадени во Чекор 11.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body","before":"*The detailed explanatory panel for this node is not opened in the recording; the node title and pacing are visible.*","after":"*Only the node title and pacing are specified.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body_mk","before":"*Деталниот објаснувачки панел за овој јазол не е отворен во снимката; видливи се насловот на јазолот и темпото.*","after":"*Наведени се само насловот и темпото на јазолот.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body","before":"*The node's separate detailed instruction panel is not displayed in the recording.*","after":"*Separate detailed instructions for this node are not provided.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body_mk","before":"*Посебниот панел со детални упатства за јазолот не е прикажан во снимката.*","after":"*Не се дадени посебни детални упатства за овој јазол.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body","before":"*The recording shows the node and its connection to the next step, but does not expose a detailed instruction panel for this node.*","after":"*The node and its connection to the next step are specified, but no detailed instructions are provided.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body_mk","before":"*Снимката го покажува јазолот и неговата врска со следниот чекор, но не открива детален панел со упатства за него.*","after":"*Наведени се јазолот и неговата врска со следниот чекор, но не се дадени детални упатства.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body","before":"*No separate detailed instruction panel for this node is displayed in the recording.*","after":"*No separate detailed instructions are provided for this node.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-no-pitch","field":"body_mk","before":"*Во снимката не е прикажан посебен детален панел со упатства за овој јазол.*","after":"*За овој јазол не се дадени посебни детални упатства.*","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body","before":"# 9. WHAT THE RECORDING DOES AND DOES NOT ESTABLISH","after":"# 9. WORKFLOW SCOPE","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body_mk","before":"# 9. ШТО ПОТВРДУВА И ШТО НЕ ПОТВРДУВА СНИМКАТА","after":"# 9. ОПФАТ НА РАБОТНИОТ ТЕК","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body","before":"## Explicitly shown in the recording","after":"## Included in this workflow","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body_mk","before":"## Изречно прикажано во снимката","after":"## Вклучено во овој работен тек","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body","before":"The recording does not expose detailed instruction panels for every node. In particular, the individual instructions for No Pitch, They Don't Want It Sexual, Relationship Building, and Continue Normal Conversation (No Pitch) are not fully shown.","after":"Detailed instructions are not provided for every node. In particular, the individual instructions for No Pitch, They Don't Want It Sexual, Relationship Building, and Continue Normal Conversation (No Pitch) are not fully specified.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body_mk","before":"Снимката не открива детални панели со упатства за секој јазол. Особено, поединечните упатства за Без понуда, Не сака сексуален разговор, Градење однос и Продолжи нормален разговор (без понуда) не се целосно прикажани.","after":"Не се дадени детални упатства за секој јазол. Особено, поединечните упатства за Без понуда, Не сака сексуален разговор, Градење однос и Продолжи нормален разговор (без понуда) не се целосно наведени.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body","before":"The recording also does not provide a complete library of verbatim chat messages, specific PPV prices, customer segmentation rules, or platform-specific operating procedures.","after":"This workflow does not include a complete library of verbatim chat messages, specific PPV prices, customer segmentation rules, or platform-specific operating procedures.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."},{"unit_id":"flow-reference","field":"body_mk","before":"Снимката исто така не дава целосна библиотека со дословни пораки, конкретни PPV-цени, правила за сегментација на клиенти или постапки специфични за платформата.","after":"Овој работен тек не вклучува целосна библиотека со дословни пораки, конкретни PPV-цени, правила за сегментација на клиенти или постапки специфични за платформата.","reason":"Remove references to a training video, recording or absent clip; keep the instruction or example."}]}$payload$::jsonb; item jsonb; current_text text; u evzon_private.training_units;
begin
 for item in select * from jsonb_array_elements(payload->'units') loop
  select * into u from evzon_private.training_units where id=item->>'id' for update;
  if u.id is null or md5(u.body)<>item->>'before_en' or md5(u.body_mk)<>item->>'before_mk' or u.revision<>(item->>'revision')::integer then raise exception 'Guide changed since review; no changes applied';end if;
 end loop;
 for item in select * from jsonb_array_elements(payload->'edits') loop
  select case when item->>'field'='body' then body when item->>'field'='body_mk' then body_mk else null end into current_text from evzon_private.training_units where id=item->>'unit_id';
  if current_text is null or length(item->>'before')=0 or (length(current_text)-length(replace(current_text,item->>'before','')))/length(item->>'before')<>1 then raise exception 'Expected guide passage not found exactly once';end if;
  update evzon_private.training_units set body=case when item->>'field'='body' then replace(body,item->>'before',item->>'after') else body end,body_mk=case when item->>'field'='body_mk' then replace(body_mk,item->>'before',item->>'after') else body_mk end,updated_at=now() where id=item->>'unit_id';
 end loop;
 for item in select * from jsonb_array_elements(payload->'units') loop
  select * into u from evzon_private.training_units where id=item->>'id';
  if md5(u.body)<>item->>'after_en' or md5(u.body_mk)<>item->>'after_mk' or u.revision<>(item->>'revision')::integer then raise exception 'Guide verification failed; no changes applied';end if;
 end loop;
 if exists(select 1 from evzon_private.exam_questions q join evzon_private.training_units guide on guide.id=q.unit_id where strpos(guide.body,q.source_anchor)=0) then raise exception 'An exam question lost its guide reference; no changes applied';end if;
end $release$;
commit;
select 'Training-video references removed in both languages. Progress and exam sources preserved.' as result;
